output_path="${SQUEALGEN_OUTPUT_PATH:-squealgen}"

cat > "${output_path}" <<'EOF'
#!/bin/bash
# NB: this file is generated by mksquealgen.sh, don't edit it directly

if [ "$#" -lt 3 ]; then
    echo "Usage: squealgen DBNAME MODULENAME SCHEMA [IMPORTS]";
    exit 1;
fi
DBNAME=$1
MODULENAME=$2
SCHEMA=$3
IMPORTS=$4 # this can be empty.
EOF

echo 'PSQLCMD=${PSQLCMD:-psql}' >> "${output_path}"
echo '$PSQLCMD -d "${DBNAME}" -v chosen_schema="${SCHEMA}" -v modulename="${MODULENAME}" -v extra_imports="${IMPORTS}" <<"EOF"' >> "${output_path}"
cat squealgen.sql >> "${output_path}"
echo "EOF" >> "${output_path}"
chmod 755 "${output_path}"
